export const getUniqueEquipes = () => [...new Set(salesData.map(d => d.equipe))];
export const getUniqueVendedores = () => [...new Set(salesData.map(d => d.vendedor))];
export const getVendedoresByEquipe = (equipe: string) => {
  if (!equipe || equipe === "all") {
    return getUniqueVendedores();
  }
  return [...new Set(salesData.filter(d => d.equipe === equipe).map(d => d.vendedor))];
};
export const getUniqueMeses = () => [...new Set(salesData.map(d => d.mes))];
export const getUniqueAnos = () => {
  const anos = [...new Set(salesData.map(d => d.ano))];
  // Ordena em ordem decrescente para garantir anos mais recentes primeiro
  return anos.sort((a, b) => b - a);
};
export const getUniqueRevendas = () => [...new Set(salesData.map(d => d.revenda))];
export const getUniqueBalconistas = () => [...new Set(salesData.map(d => d.balconista))];
